out$avelogcpm_zero <- aveLogCPM(matrix(0, 7, 4))
# Fix 6: cpmByGroup resolves dispersion via getDispersion (tagwise first)
dge6 <- DGEList(counts6, group=group6)
dge6$common.dispersion <- 0.1
dge6$tagwise.dispersion <- tagwise_disp6
out$cpmbygroup_tagwise <- cpmByGroup(dge6)
# Fix 7: binomTest chi-squared branch (chisq.test default correct=TRUE)
out$binom_chisq <- binomTest(y1_7, y2_7, n1=n1_7, n2=n2_7)
# Fix 8: binomTest small-probability branch (order(d)+cumsum, no tolerance)
out$binom_smallp <- binomTest(y1_8, y2_8, n1=n1_8, n2=n2_8)
# Fix 9: WLEB unimodality backfill loop, locfit.mixed only
out$wleb_mixed <- edgeR:::WLEB(theta9, loglik9, covariate=covariate9, trend.method="locfit.mixed", overall=FALSE, trend=FALSE, individual=FALSE, m0.out=TRUE)$shared.loglik
# Fix 11: q2qnbinom far tail (dispersion=0; log-tails past -744)
out$q2q_far <- q2qnbinom(x11, input_mean11, output_mean11, dispersion=0)

# ===== print each reference as a Python literal (row-major) =====
pyfmt <- function(x) {
  if (is.matrix(x)) {
    rows <- apply(x, 1, function(r) paste(sprintf("%.15g", r), collapse=", "))
    paste0("[", paste0("[", rows, "]", collapse=",\n  "), "]")
  } else paste0("[", paste(sprintf("%.15g", as.vector(x)), collapse=", "), "]")
}
unlink("edger5_fixes_refs.txt")
for (nm in names(out)) {
  cat(nm, pyfmt(out[[nm]]), sep="\t", file="edger5_fixes_refs.txt", append=TRUE)
  cat("\n", file="edger5_fixes_refs.txt", append=TRUE)
}
cat("edgeR", as.character(packageVersion("edgeR")), "R", as.character(getRversion()), "\n", file="edger5_fixes_refs.txt", append=TRUE)
